-- Appliquer une seule fois après la migration 002. Aucune réponse ni aucun carnet supprimé.
begin;
alter table public.academy_lessons add column objectives text[];
alter table public.academy_reading_pages add column required boolean not null default true;
alter table public.academy_requirements add column source_kind text not null default 'manual' check(source_kind in ('activity','manual','supplement'));
alter table public.academy_requirements add column source_title text not null default '';
alter table public.academy_requirements add column last_page integer;
create table public.academy_documents(level integer primary key check(level between 1 and 4),first_course_page integer not null,last_course_page integer not null,presentation_pages integer[] not null,summary_pages integer[] not null,excluded_pages integer[] not null);
create table public.academy_slide_routes(level integer not null,step integer not null,positions integer[] not null,primary key(level,step),foreign key(level,step) references public.academy_lessons(level,step));
create table public.academy_slide_sources(level integer not null,position integer not null,first_page integer not null,last_page integer not null,primary key(level,position));
alter table public.academy_documents enable row level security;
alter table public.academy_slide_routes enable row level security;
alter table public.academy_slide_sources enable row level security;
revoke all on public.academy_documents,public.academy_slide_routes,public.academy_slide_sources from public,anon,authenticated;
grant select on public.academy_documents,public.academy_slide_routes,public.academy_slide_sources to authenticated;
create policy documents_read on public.academy_documents for select to authenticated using(public.academy_has_access(level) or public.academy_is_admin());
create policy routes_read on public.academy_slide_routes for select to authenticated using(public.academy_has_access(level) or public.academy_is_admin());
create policy slide_sources_read on public.academy_slide_sources for select to authenticated using(public.academy_has_access(level) or public.academy_is_admin());
