ep": 10, "title": "Automatiser un processus", "first_page": 42, "last_page": 44, "objectives": ["Préparer une automatisation réversible", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 2, "step": 11, "title": "Évaluation et projet", "first_page": 45, "last_page": 54, "objectives": ["Démontrer le gain d’un processus", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 2, "step": 12, "title": "Ressources et suite du parcours", "first_page": 55, "last_page": 58, "objectives": ["Consolider son système de travail", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 1, "title": "Architecture des transformeurs", "first_page": 5, "last_page": 5, "objectives": ["Expliquer les rôles de l’attention, de la position et des connexions résiduelles dans un transformeur.", "Relier ces composants à un système génératif sans confondre modèle et interface."]}, {"level": 3, "step": 2, "title": "Embeddings et recherche vectorielle", "first_page": 6, "last_page": 6, "objectives": ["Évaluer un moteur de recherche vectorielle", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 3, "title": "RAG avancé", "first_page": 7, "last_page": 8, "objectives": ["Comparer deux stratégies de RAG", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 4, "title": "Agents et appels d’outils", "first_page": 9, "last_page": 10, "objectives": ["Limiter les droits d’un agent", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 5, "title": "Fine-tuning, LoRA et PEFT", "first_page": 11, "last_page": 12, "objectives": ["Choisir entre RAG et adaptation du modèle", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 6, "title": "Évaluation, sécurité et lexique", "first_page": 13, "last_page": 16, "objectives": ["Tester les protections d’un assistant", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 7, "title": "Ateliers techniques guidés", "first_page": 17, "last_page": 23, "objectives": ["Construire un prototype reproductible", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 8, "title": "Études de cas", "first_page": 24, "last_page": 26, "objectives": ["Comparer deux architectures métier", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 9, "title": "Templates réutilisables", "first_page": 27, "last_page": 28, "objectives": ["Versionner les contrats de sortie", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 10, "title": "Évaluation et projet", "first_page": 29, "last_page": 36, "objectives": ["Soutenir un assistant métier", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 3, "step": 11, "title": "Ressources et suite du parcours", "first_page": 37, "last_page": 39, "objectives": ["Organiser le suivi après livraison", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 1, "title": "Panorama des usages métier", "first_page": 5, "last_page": 7, "objectives": ["Prioriser les usages d’un secteur", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 2, "title": "Données et confidentialité", "first_page": 8, "last_page": 9, "objectives": ["Classifier les données d’un cas d’usage", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 3, "title": "Conduite du changement", "first_page": 10, "last_page": 10, "objectives": ["Préparer l’adoption par une équipe", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 4, "title": "Gouvernance et charte d’usage", "first_page": 11, "last_page": 12, "objectives": ["Rédiger une charte d’usage opérationnelle", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 5, "title": "Cadrage de projet et lexique", "first_page": 13, "last_page": 16, "objectives": ["Cadrer un projet testable", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 6, "title": "Ateliers guidés", "first_page": 17, "last_page": 22, "objectives": ["Tester un kit métier", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 7, "title": "Études de cas sectorielles", "first_page": 23, "last_page": 39, "objectives": ["Analyser un cas sectoriel", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 8, "title": "Templates métier", "first_page": 40, "last_page": 47, "objectives": ["Adapter un template de prompt à un métier, renseigner ses variables et vérifier sa sortie.", "Comparer les limites et risques de deux templates sectoriels."]}, {"level": 4, "step": 9, "title": "Évaluation et projet sectoriel", "first_page": 48, "last_page": 55, "objectives": ["Présenter le projet sectoriel", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}, {"level": 4, "step": 10, "title": "Ressources et suite du parcours", "first_page": 56, "last_page": 59, "objectives": ["Planifier l’amélioration continue", "Produire le livrable et vérifier les critères de réussite ci-dessous."]}]$catalog$) x where l.level=x.level and l.step=x.step;
update public.academy_reading_pages p set required=not (p.page=any(d.excluded_pages)) from public.academy_documents d where d.level=p.level;
update public.academy_requirements r set title=x.title,page=x.page,last_page=x.last_page,source_kind=x.source_kind,source_title=x.source_title,instruction=x.instruction from json_populate_recordset(null::public.academy_requirements,$catalog$[{"id": "n1-s1-activite", "level": 1, "step": 1, "kind": "activite", "title": "Découvrir l’IA générative", "page": 4, "instruction": "Comparez deux réponses d’un chatbot à une demande de présentation d’une association locale. Livrable : Un tableau de deux usages et deux limites ; distinguer l’outil du modèle et signaler les faits non vérifiés.", "last_page": 8, "source_kind": "activity", "source_title": "Découvrir l’IA générative"}, {"id": "n1-s2-activite", "level": 1, "step": 2, "kind": "activite", "title": "Lexique et mécanismes", "page": 9, "instruction": "Réécrivez une même demande courte et détaillée, puis observez ce qui change sans attribuer toutes les variations à un seul paramètre. Livrable : Un glossaire de six termes et deux essais ; ne pas supposer un nombre fixe de tokens par mot ni une vérité garantie par la température.", "last_page": 13, "source_kind": "activity", "source_title": "Lexique et mécanismes"}, {"id": "n1-s3-activite", "level": 1, "step": 3, "kind": "activite", "title": "Histoire, limites et enjeux", "page": 14, "instruction": "Vérifiez une réponse contenant trois affirmations factuelles avec des sources identifiables. Livrable : Une fiche affirmation/source/conclusion ; séparer fait confirmé, doute et erreur ; aucune donnée sensible utilisée.", "last_page": 17, "source_kind": "activity", "source_title": "Histoire, limites et enjeux"}, {"id": "n1-s4-activite", "level": 1, "step": 4, "kind": "activite", "title": "Structurer un prompt", "page": 18, "instruction": "Rédigez un prompt pour une annonce de formation en précisant public, tâche, contexte, contraintes et format. Livrable : Le prompt, la réponse et une révision ; au moins cinq critères explicites et un contrôle des faits.", "last_page": 20, "source_kind": "activity", "source_title": "Structurer un prompt"}, {"id": "n1-s5-activite", "level": 1, "step": 5, "kind": "activite", "title": "Ateliers guidés", "page": 21, "instruction": "Testez un brouillon de message client puis améliorez sa clarté et son format. Livrable : Deux prompts et deux sorties annotées ; justifier trois corrections avec les critères attendus.", "last_page": 23, "source_kind": "activity", "source_title": "Ateliers guidés"}, {"id": "n1-s6-activite", "level": 1, "step": 6, "kind": "activite", "title": "Études de cas et modèles", "page": 24, "instruction": "Choisissez une association, un commerce ou un service et adaptez un modèle de réponse à son besoin. Livrable : Une fiche de cas anonymisée, un prompt réutilisable et un contre-exemple ; les variables doivent être identifiables.", "last_page": 27, "source_kind": "activity", "source_title": "Études de cas et modèles"}, {"id": "n1-s7-activite", "level": 1, "step": 7, "kind": "activite", "title": "Évaluation et projet", "page": 28, "instruction": "Rassemblez cinq prompts, leurs essais et l’analyse de leurs limites ; demandez au formateur la session d’évaluation supervisée. Livrable : Un dossier structuré et une auto-évaluation selon la grille /60 ; la lecture des corrigés ne vaut pas réussite à l’examen.", "last_page": 36, "source_kind": "activity", "source_title": "Évaluation et projet"}, {"id": "n1-s8-activite", "level": 1, "step": 8, "kind": "activite", "title": "Ressources et suite du parcours", "page": 37, "instruction": "Choisissez deux ressources du manuel et planifiez trois usages à tester pendant les deux prochaines semaines. Livrable : Un plan daté avec objectifs, sources et critères de progrès ; sélectionner N2 uniquement après examen des prérequis.", "last_page": 41, "source_kind": "activity", "source_title": "Ressources et suite du parcours"}, {"id": "n1-exercice-1", "level": 1, "step": 1, "kind": "exercice", "title": "Découverte des LLM", "page": 7, "instruction": "Réalisez « Découverte des LLM » en vous appuyant sur les consignes du manuel à partir de la page 7. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 8, "source_title": "Découverte des LLM"}, {"id": "n1-exercice-2", "level": 1, "step": 2, "kind": "exercice", "title": "Quiz lexique", "page": 10, "instruction": "Réalisez « Quiz lexique » en vous appuyant sur les consignes du manuel à partir de la page 10. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 10, "source_title": "Quiz lexique"}, {"id": "n1-exercice-3", "level": 1, "step": 2, "kind": "exercice", "title": "Tokenisation manuelle", "page": 10, "instruction": "Réalisez « Tokenisation manuelle » en vous appuyant sur les consignes du manuel à partir de la page 10. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 11, "source_title": "Tokenisation manuelle"}, {"id": "n1-exercice-4", "level": 1, "step": 2, "kind": "exercice", "title": "Limite de contexte", "page": 12, "instruction": "Réalisez « Limite de contexte » en vous appuyant sur les consignes du manuel à partir de la page 12. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 12, "source_title": "Limite de contexte"}, {"id": "n1-exercice-5", "level": 1, "step": 2, "kind": "exercice", "title": "Test de température", "page": 13, "instruction": "Réalisez « Test de température » en vous appuyant sur les consignes du manuel à partir de la page 13. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 13, "source_title": "Test de température"}, {"id": "n1-exercice-6", "level": 1, "step": 3, "kind": "exercice", "title": "Débat éthique", "page": 16, "instruction": "Réalisez « Débat éthique » en vous appuyant sur les consignes du manuel à partir de la page 16. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 17, "source_title": "Débat éthique"}, {"id": "n1-exercice-7", "level": 1, "step": 4, "kind": "exercice", "title": "Transformation de prompts", "page": 19, "instruction": "Réalisez « Transformation de prompts » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 19, "source_title": "Transformation de prompts"}, {"id": "n1-exercice-8", "level": 1, "step": 4, "kind": "exercice", "title": "Création de prompts", "page": 20, "instruction": "Réalisez « Création de prompts » en vous appuyant sur les consignes du manuel à partir de la page 20. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 20, "source_title": "Création de prompts"}, {"id": "n1-atelier-9", "level": 1, "step": 5, "kind": "atelier", "title": "Premiers pas avec un chatbot", "page": 21, "instruction": "Réalisez « Premiers pas avec un chatbot » en vous appuyant sur les consignes du manuel à partir de la page 21. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 21, "source_title": "Premiers pas avec un chatbot"}, {"id": "n1-atelier-10", "level": 1, "step": 5, "kind": "atelier", "title": "Détection des hallucinations", "page": 22, "instruction": "Réalisez « Détection des hallucinations » en vous appuyant sur les consignes du manuel à partir de la page 22. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 22, "source_title": "Détection des hallucinations"}, {"id": "n1-atelier-11", "level": 1, "step": 5, "kind": "atelier", "title": "Génération de texte", "page": 23, "instruction": "Réalisez « Génération de texte » en vous appuyant sur les consignes du manuel à partir de la page 23. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 23, "source_title": "Génération de texte"}, {"id": "n1-atelier-12", "level": 1, "step": 5, "kind": "atelier", "title": "Génération d’images — complément du parcours", "page": 23, "instruction": "Complément au sommaire : créez deux variantes d’une image pour une association locale. Décrivez les prompts, comparez cadrage et lisibilité, expliquez les limites et les droits des éléments utilisés.", "source_kind": "supplement", "last_page": 23, "source_title": "Consigne complémentaire du parcours"}, {"id": "n1-cas-13", "level": 1, "step": 6, "kind": "cas", "title": "Service client : traiter trois demandes", "page": 24, "instruction": "Réalisez « Service client : traiter trois demandes » en vous appuyant sur les consignes du manuel à partir de la page 24. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 25, "source_title": "Service client : traiter trois demandes"}, {"id": "n1-cas-14", "level": 1, "step": 6, "kind": "cas", "title": "Note de synthèse", "page": 25, "instruction": "Réalisez « Note de synthèse » en vous appuyant sur les consignes du manuel à partir de la page 25. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 26, "source_title": "Note de synthèse"}, {"id": "n1-cas-15", "level": 1, "step": 6, "kind": "cas", "title": "Brainstorming produit — complément du parcours", "page": 27, "instruction": "Complément au sommaire : proposez cinq idées de produit utiles localement, comparez faisabilité et public cible, retenez une idée et justifiez votre choix. Présentez les prompts et votre vérification critique.", "source_kind": "supplement", "last_page": 27, "source_title": "Consigne complémentaire du parcours"}, {"id": "n1-fil_rouge-16", "level": 1, "step": 7, "kind": "fil_rouge", "title": "Projet fil rouge N1", "page": 31, "instruction": "Réalisez « Projet fil rouge N1 » en vous appuyant sur les consignes du manuel à partir de la page 31. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 33, "source_title": "Projet fil rouge N1"}, {"id": "n2-s1-activite", "level": 2, "step": 1, "kind": "activite", "title": "Objectifs et prérequis", "page": 4, "instruction": "Analysez une tâche répétitive de votre activité et expliquez comment vous la réalisez aujourd’hui. Livrable : Une fiche processus, fréquence, difficultés et résultat attendu ; distinguer observation et estimation.", "last_page": 4, "source_kind": "activity", "source_title": "Objectifs et prérequis"}, {"id": "n2-s2-activite", "level": 2, "step": 2, "kind": "activite", "title": "Apprendre par exemples : few-shot", "page": 5, "instruction": "Créez trois exemples d’entrée-sortie pour classer des demandes clients, puis testez un cas absent des exemples. Livrable : Trois exemples et un jeu de cinq tests ; inclure une catégorie ambiguë et documenter une erreur.", "last_page": 8, "source_kind": "activity", "source_title": "Apprendre par exemples : few-shot"}, {"id": "n2-s3-activite", "level": 2, "step": 3, "kind": "activite", "title": "Décomposer une tâche", "page": 9, "instruction": "Découpez la préparation d’un compte rendu en extraction, synthèse et contrôle, sans demander une pensée interne. Livrable : Trois sous-consignes avec entrées et sorties ; une justification concise et vérifiable suffit.", "last_page": 11, "source_kind": "activity", "source_title": "Décomposer une tâche"}, {"id": "n2-s4-activite", "level": 2, "step": 4, "kind": "activite", "title": "Construire un workflow", "page": 12, "instruction": "Concevez un flux brouillon → vérification → mise en forme pour une note professionnelle. Livrable : Un schéma et trois prompts ; prévoir le rejet d’une entrée incomplète et une validation humaine.", "last_page": 16, "source_kind": "activity", "source_title": "Construire un workflow"}, {"id": "n2-s5-activite", "level": 2, "step": 5, "kind": "activite", "title": "Évaluer et fiabiliser les sorties", "page": 17, "instruction": "Définissez un jeu de dix demandes et comparez deux prompts avec la même grille. Livrable : Un tableau de résultats ; exactitude, complétude et format sont évalués séparément.", "last_page": 22, "source_kind": "activity", "source_title": "Évaluer et fiabiliser les sorties"}, {"id": "n2-s6-activite", "level": 2, "step": 6, "kind": "activite", "title": "Introduction au RAG et lexique", "page": 23, "instruction": "Préparez trois extraits documentaires et demandez une réponse limitée à ces extraits. Livrable : Question, extraits et réponse citée ; signaler l’absence de réponse quand la source manque.", "last_page": 27, "source_kind": "activity", "source_title": "Introduction au RAG et lexique"}, {"id": "n2-s7-activite", "level": 2, "step": 7, "kind": "activite", "title": "Ateliers guidés", "page": 29, "instruction": "Construisez un assistant de rédaction à partir d’un brief anonymisé et de deux exemples. Livrable : Un prompt système, trois essais et une grille ; éviter d’inclure des données personnelles.", "last_page": 32, "source_kind": "activity", "source_title": "Ateliers guidés"}, {"id": "n2-s8-activite", "level": 2, "step": 8, "kind": "activite", "title": "Études de cas métier", "page": 33, "instruction": "Choisissez un cas du chapitre : compte rendu de réunion, proposition commerciale ou FAQ interne. Repérez les décisions exigeant une intervention humaine. Livrable : Une fiche contexte, entrées, sortie, vérifications et décisions réservées à une personne ; utilisez des données fictives ou autorisées.", "last_page": 37, "source_kind": "activity", "source_title": "Études de cas métier"}, {"id": "n2-s9-activite", "level": 2, "step": 9, "kind": "activite", "title": "Bibliothèque de prompts", "page": 38, "instruction": "Classez cinq prompts par usage, version et données nécessaires. Livrable : Cinq fiches avec variables, contraintes, exemple de sortie et test de non-régression.", "last_page": 41, "source_kind": "activity", "source_title": "Bibliothèque de prompts"}, {"id": "n2-s10-activite", "level": 2, "step": 10, "kind": "activite", "title": "Automatiser un processus", "page": 42, "instruction": "Décrivez un déclencheur, les transformations, la validation et la sortie d’un processus. Livrable : Un protocole de test avec cas normal, donnée absente et erreur ; aucune action externe sans validation prévue.", "last_page": 44, "source_kind": "activity", "source_title": "Automatiser un processus"}, {"id": "n2-s11-activite", "level": 2, "step": 11, "kind": "activite", "title": "Évaluation et projet", "page": 45, "instruction": "Remettez le processus initial, cinq prompts, les résultats mesurés et les risques ; préparez le QCM supervisé. Livrable : Dossier évalué sur 70 ; calculs reproductibles, limites et données de comparaison explicites.", "last_page": 54, "source_kind": "activity", "source_title": "Évaluation et projet"}, {"id": "n2-s12-activite", "level": 2, "step": 12, "kind": "activite", "title": "Ressources et suite du parcours", "page": 55, "instruction": "Choisissez deux routines et une fréquence de révision des prompts. Livrable : Un plan de maintenance et un journal d’essais ; définir quand arrêter une automatisation défaillante.", "last_page": 58, "source_kind": "activity", "source_title": "Ressources et suite du parcours"}, {"id": "n2-exercice-1", "level": 2, "step": 2, "kind": "exercice", "title": "Zero-shot vers few-shot", "page": 6, "instruction": "Réalisez « Zero-shot vers few-shot » en vous appuyant sur les consignes du manuel à partir de la page 6. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 6, "source_title": "Zero-shot vers few-shot"}, {"id": "n2-exercice-2", "level": 2, "step": 2, "kind": "exercice", "title": "Créer des prompts few-shot", "page": 6, "instruction": "Réalisez « Créer des prompts few-shot » en vous appuyant sur les consignes du manuel à partir de la page 6. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 8, "source_title": "Créer des prompts few-shot"}, {"id": "n2-exercice-3", "level": 2, "step": 3, "kind": "exercice", "title": "Décomposer et vérifier une résolution — exercice 2.3", "page": 10, "instruction": "Réalisez « Décomposer et vérifier une résolution — exercice 2.3 » en vous appuyant sur les consignes du manuel à partir de la page 10. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne. Demandez des étapes de résolution vérifiables et des justifications synthétiques ; ne demandez pas une pensée interne cachée.", "source_kind": "manual", "last_page": 11, "source_title": "Décomposer et vérifier une résolution — exercice 2.3"}, {"id": "n2-exercice-4", "level": 2, "step": 4, "kind": "exercice", "title": "Décomposer une tâche complexe", "page": 14, "instruction": "Réalisez « Décomposer une tâche complexe » en vous appuyant sur les consignes du manuel à partir de la page 14. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 16, "source_title": "Décomposer une tâche complexe"}, {"id": "n2-exercice-5", "level": 2, "step": 5, "kind": "exercice", "title": "Audit de réponses générées", "page": 18, "instruction": "Réalisez « Audit de réponses générées » en vous appuyant sur les consignes du manuel à partir de la page 18. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 18, "source_title": "Audit de réponses générées"}, {"id": "n2-exercice-6", "level": 2, "step": 5, "kind": "exercice", "title": "Détection et correction des biais", "page": 19, "instruction": "Réalisez « Détection et correction des biais » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 20, "source_title": "Détection et correction des biais"}, {"id": "n2-exercice-7", "level": 2, "step": 5, "kind": "exercice", "title": "Audit de sécurité — exercice 2.7", "page": 21, "instruction": "Réalisez « Audit de sécurité — exercice 2.7 » en vous appuyant sur les consignes du manuel à partir de la page 21. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 22, "source_title": "Audit de sécurité — exercice 2.7"}, {"id": "n2-exercice-8", "level": 2, "step": 6, "kind": "exercice", "title": "Pipeline RAG simple — second exercice 2.7", "page": 24, "instruction": "Réalisez « Pipeline RAG simple — second exercice 2.7 » en vous appuyant sur les consignes du manuel à partir de la page 24. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 25, "source_title": "Pipeline RAG simple — second exercice 2.7"}, {"id": "n2-exercice-9", "level": 2, "step": 9, "kind": "exercice", "title": "Templates personnalisés", "page": 40, "instruction": "Réalisez « Templates personnalisés » en vous appuyant sur les consignes du manuel à partir de la page 40. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 41, "source_title": "Templates personnalisés"}, {"id": "n2-exercice-10", "level": 2, "step": 10, "kind": "exercice", "title": "Automatisation d’un processus personnel", "page": 43, "instruction": "Réalisez « Automatisation d’un processus personnel » en vous appuyant sur les consignes du manuel à partir de la page 43. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 44, "source_title": "Automatisation d’un processus personnel"}, {"id": "n2-atelier-11", "level": 2, "step": 7, "kind": "atelier", "title": "Prompt vague vers prompt structuré", "page": 29, "instruction": "Réalisez « Prompt vague vers prompt structuré » en vous appuyant sur les consignes du manuel à partir de la page 29. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 29, "source_title": "Prompt vague vers prompt structuré"}, {"id": "n2-atelier-12", "level": 2, "step": 7, "kind": "atelier", "title": "Few-shot avec exemples", "page": 30, "instruction": "Réalisez « Few-shot avec exemples » en vous appuyant sur les consignes du manuel à partir de la page 30. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 30, "source_title": "Few-shot avec exemples"}, {"id": "n2-atelier-13", "level": 2, "step": 7, "kind": "atelier", "title": "Chaînage de cinq prompts", "page": 30, "instruction": "Réalisez « Chaînage de cinq prompts » en vous appuyant sur les consignes du manuel à partir de la page 30. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 31, "source_title": "Chaînage de cinq prompts"}, {"id": "n2-atelier-14", "level": 2, "step": 7, "kind": "atelier", "title": "Évaluation et grille de test", "page": 31, "instruction": "Réalisez « Évaluation et grille de test » en vous appuyant sur les consignes du manuel à partir de la page 31. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 32, "source_title": "Évaluation et grille de test"}, {"id": "n2-cas-15", "level": 2, "step": 8, "kind": "cas", "title": "Compte rendu de réunion", "page": 33, "instruction": "Réalisez « Compte rendu de réunion » en vous appuyant sur les consignes du manuel à partir de la page 33. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 34, "source_title": "Compte rendu de réunion"}, {"id": "n2-cas-16", "level": 2, "step": 8, "kind": "cas", "title": "Proposition commerciale", "page": 34, "instruction": "Réalisez « Proposition commerciale » en vous appuyant sur les consignes du manuel à partir de la page 34. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 36, "source_title": "Proposition commerciale"}, {"id": "n2-cas-17", "level": 2, "step": 8, "kind": "cas", "title": "Support interne à partir d’une FAQ", "page": 36, "instruction": "Réalisez « Support interne à partir d’une FAQ » en vous appuyant sur les consignes du manuel à partir de la page 36. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 37, "source_title": "Support interne à partir d’une FAQ"}, {"id": "n2-fil_rouge-18", "level": 2, "step": 11, "kind": "fil_rouge", "title": "Transformation d’un processus métier réel", "page": 49, "instruction": "Réalisez « Transformation d’un processus métier réel » en vous appuyant sur les consignes du manuel à partir de la page 49. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 52, "source_title": "Transformation d’un processus métier réel"}, {"id": "n3-s1-activite", "level": 3, "step": 1, "kind": "activite", "title": "Objectifs et architecture des modèles", "page": 5, "instruction": "Dessinez une architecture simplifiée de transformeur : tokens, attention, position, connexions résiduelles et normalisation. Reliez-la à une application en distinguant interface, modèle, outils et données. Livrable : Un schéma annoté et une explication des rôles de chaque composant ; distinguez mécanisme du modèle et fonctions de l’application.", "last_page": 5, "source_kind": "activity", "source_title": "Architecture des transformeurs"}, {"id": "n3-s2-activite", "level": 3, "step": 2, "kind": "activite", "title": "Embeddings et recherche vectorielle", "page": 6, "instruction": "Définissez dix requêtes et les passages attendus sur un petit corpus autorisé. Livrable : Un jeu de pertinence et un indicateur de rappel ; documenter les requêtes sans réponse.", "last_page": 6, "source_kind": "activity", "source_title": "Embeddings et recherche vectorielle"}, {"id": "n3-s3-activite", "level": 3, "step": 3, "kind": "activite", "title": "RAG avancé", "page": 7, "instruction": "Comparez deux découpages du même corpus en conservant modèle et questions identiques. Livrable : Résultats sourcés, coût et latence observés ; isoler les erreurs de recherche des erreurs de génération.", "last_page": 8, "source_kind": "activity", "source_title": "RAG avancé"}, {"id": "n3-s4-activite", "level": 3, "step": 4, "kind": "activite", "title": "Agents et appels d’outils", "page": 9, "instruction": "Concevez un outil de consultation et un outil d’action avec validation explicite. Livrable : Schéma d’autorisations et trois tests ; refuser arguments invalides et action non autorisée.", "last_page": 10, "source_kind": "activity", "source_title": "Agents et appels d’outils"}, {"id": "n3-s5-activite", "level": 3, "step": 5, "kind": "activite", "title": "Fine-tuning, LoRA et PEFT", "page": 11, "instruction": "Analysez une tâche de style et une tâche de connaissance documentaire ; proposez la méthode adaptée. Livrable : Une décision argumentée avec données, coûts, métriques et limites ; prévoir un jeu de validation indépendant.", "last_page": 12, "source_kind": "activity", "source_title": "Fine-tuning, LoRA et PEFT"}, {"id": "n3-s6-activite", "level": 3, "step": 6, "kind": "activite", "title": "Évaluation, sécurité et lexique", "page": 13, "instruction": "Écrivez cinq entrées adverses, dont une instruction hostile dans un document fourni. Livrable : Un tableau entrée/résultat attendu/résultat observé ; aucune donnée ou clé sensible dans les journaux.", "last_page": 16, "source_kind": "activity", "source_title": "Évaluation, sécurité et lexique"}, {"id": "n3-s7-activite", "level": 3, "step": 7, "kind": "activite", "title": "Ateliers techniques guidés", "page": 17, "instruction": "Implémentez le pipeline du manuel dans un environnement isolé avec un petit corpus non sensible. Livrable : Code, dépendances, configuration d’exemple sans secret et tests ; documenter une exécution reproductible.", "last_page": 23, "source_kind": "activity", "source_title": "Ateliers techniques guidés"}, {"id": "n3-s8-activite", "level": 3, "step": 8, "kind": "activite", "title": "Études de cas", "page": 24, "instruction": "Comparez un support client documentaire et un assistant d’analyse de documents. Livrable : Deux fiches d’architecture ; préciser responsabilités, critères de succès et cas de refus.", "last_page": 26, "source_kind": "activity", "source_title": "Études de cas"}, {"id": "n3-s9-activite", "level": 3, "step": 9, "kind": "activite", "title": "Templates réutilisables", "page": 27, "instruction": "Définissez un schéma de réponse et un prompt d’évaluation réutilisable. Livrable : Un schéma validable, exemples valides/invalides et tests ; rejeter les champs inattendus.", "last_page": 28, "source_kind": "activity", "source_title": "Templates réutilisables"}, {"id": "n3-s10-activite", "level": 3, "step": 10, "kind": "activite", "title": "Évaluation et projet", "page": 29, "instruction": "Remettez code, corpus autorisé, évaluations, garde-fous et documentation ; préparez l’évaluation supervisée. Livrable : Projet /70 et QCM ramené à /30 dans le total ; distinguer résultats mesurés et limites connues.", "last_page": 36, "source_kind": "activity", "source_title": "Évaluation et projet"}, {"id": "n3-s11-activite", "level": 3, "step": 11, "kind": "activite", "title": "Ressources et suite du parcours", "page": 37, "instruction": "Établissez un plan de suivi des erreurs, coûts et changements de version. Livrable : Un plan avec seuils d’alerte, responsable et procédure de retour à la version précédente.", "last_page": 39, "source_kind": "activity", "source_title": "Ressources et suite du parcours"}, {"id": "n3-atelier-1", "level": 3, "step": 7, "kind": "atelier", "title": "Pipeline RAG minimal", "page": 17, "instruction": "Réalisez « Pipeline RAG minimal » en vous appuyant sur les consignes du manuel à partir de la page 17. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 18, "source_title": "Pipeline RAG minimal"}, {"id": "n3-atelier-2", "level": 3, "step": 7, "kind": "atelier", "title": "Améliorer le retrieval", "page": 19, "instruction": "Réalisez « Améliorer le retrieval » en vous appuyant sur les consignes du manuel à partir de la page 19. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 19, "source_title": "Améliorer le retrieval"}, {"id": "n3-atelier-3", "level": 3, "step": 7, "kind": "atelier", "title": "Agent avec appels d’outils", "page": 20, "instruction": "Réalisez « Agent avec appels d’outils » en vous appuyant sur les consignes du manuel à partir de la page 20. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 20, "source_title": "Agent avec appels d’outils"}, {"id": "n3-atelier-4", "level": 3, "step": 7, "kind": "atelier", "title": "Fine-tuning LoRA", "page": 21, "instruction": "Réalisez « Fine-tuning LoRA » en vous appuyant sur les consignes du manuel à partir de la page 21. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 22, "source_title": "Fine-tuning LoRA"}, {"id": "n3-atelier-5", "level": 3, "step": 7, "kind": "atelier", "title": "Évaluation automatisée et garde-fous", "page": 23, "instruction": "Réalisez « Évaluation automatisée et garde-fous » en vous appuyant sur les consignes du manuel à partir de la page 23. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 23, "source_title": "Évaluation automatisée et garde-fous"}, {"id": "n3-cas-6", "level": 3, "step": 8, "kind": "cas", "title": "Support client documentaire", "page": 24, "instruction": "Réalisez « Support client documentaire » en vous appuyant sur les consignes du manuel à partir de la page 24. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 24, "source_title": "Support client documentaire"}, {"id": "n3-cas-7", "level": 3, "step": 8, "kind": "cas", "title": "Analyse de documents financiers", "page": 25, "instruction": "Réalisez « Analyse de documents financiers » en vous appuyant sur les consignes du manuel à partir de la page 25. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 25, "source_title": "Analyse de documents financiers"}, {"id": "n3-cas-8", "level": 3, "step": 8, "kind": "cas", "title": "Rapports au format maison", "page": 26, "instruction": "Réalisez « Rapports au format maison » en vous appuyant sur les consignes du manuel à partir de la page 26. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 26, "source_title": "Rapports au format maison"}, {"id": "n3-fil_rouge-9", "level": 3, "step": 10, "kind": "fil_rouge", "title": "Assistant métier complet", "page": 32, "instruction": "Réalisez « Assistant métier complet » en vous appuyant sur les consignes du manuel à partir de la page 32. Remettez votre démarche, votre production, les tests réalisés, leurs résultats et les limites. Utilisez des données fictives ou autorisées. Ne copiez pas simplement la consigne.", "source_kind": "manual", "last_page": 33, "source_title": "Assistant métier complet"}, {"id": "n4-s1-activite", "level": 4, "step": 1, "kind": "activite", "title": "Panorama des usages métier", "page": 5, "instruction": "Listez cinq usages dans votre métier et comparez valeur attendue, faisabilité et risques. Livrable : Une matrice et un usage prioritaire ; justifier le choix sans inventer de gain chiffré.", "last_page": 7, "source_kind": "activity", "source_title": "Panorama des usages métier"}, {"id": "n4-s2-activite", "level": 4, "step": 2, "kind": "activite", "title": "Données et confidentialité", "page": 8, "instruction": "Listez les données nécessaires puis préparez un jeu fictif ou anonymisé. Livrable : Une cartographie des données et accès ; exclure les informations inutiles et prévoir la conservation.", "last_page": 9, "source_kind": "activity", "source_title": "Données et confidentialité"}, {"id": "n4-s3-activite", "level": 4, "step": 3, "kind": "activite", "title": "Conduite du changement", "page": 10, "instruction": "Identifiez utilisateurs, responsables et objections pour un pilote limité. Livrable : Un plan d’accompagnement avec formation, support et retour d’expérience.", "last_page": 10, "source_kind": "activity", "source_title": "Conduite du changement"}, {"id": "n4-s4-activite", "level": 4, "step": 4, "kind": "activite", "title": "Gouvernance et charte d’usage", "page": 11, "instruction": "Rédigez une charte pour une équipe de votre secteur. Livrable : Règles autorisées/interdites, validation humaine et signalement ; préciser qui décide et qui contrôle.", "last_page": 12, "source_kind": "activity", "source_title": "Gouvernance et charte d’usage"}, {"id": "n4-s5-activite", "level": 4, "step": 5, "kind": "activite", "title": "Cadrage de projet et lexique", "page": 13, "instruction": "Décrivez besoin, périmètre, livrables, contraintes et critères d’arrêt. Livrable : Une fiche projet approuvable ; distinguer résultat attendu et moyens envisagés.", "last_page": 16, "source_kind": "activity", "source_title": "Cadrage de projet et lexique"}, {"id": "n4-s6-activite", "level": 4, "step": 6, "kind": "activite", "title": "Ateliers guidés", "page": 17, "instruction": "Rédigez trois prompts complémentaires et testez-les sur des données fictives. Livrable : Un kit, trois essais et corrections ; vérifier contenu, format et risques avant diffusion.", "last_page": 22, "source_kind": "activity", "source_title": "Ateliers guidés"}, {"id": "n4-s7-activite", "level": 4, "step": 7, "kind": "activite", "title": "Études de cas sectorielles", "page": 23, "instruction": "Choisissez un cas du manuel et adaptez-le à votre organisation. Livrable : Une analyse du contexte, des acteurs et des contraintes ; expliquer les adaptations nécessaires.", "last_page": 39, "source_kind": "activity", "source_title": "Études de cas sectorielles"}, {"id": "n4-s8-activite", "level": 4, "step": 8, "kind": "activite", "title": "Templates métier", "page": 40, "instruction": "Personnalisez deux templates métier du chapitre : fiche de poste, campagne, synthèse financière, analyse de contrat ou fiche d’information. Renseignez les variables et testez-les sur des données fictives. Livrable : Deux prompts adaptés, les résultats obtenus et une analyse des vérifications et limites ; aucune donnée sensible réelle.", "last_page": 47, "source_kind": "activity", "source_title": "Templates métier"}, {"id": "n4-s9-activite", "level": 4, "step": 9, "kind": "activite", "title": "Évaluation et projet sectoriel", "page": 48, "instruction": "Remettez cas d’usage, kit de prompts, risques et plan de déploiement ; préparez le QCM supervisé. Livrable : Projet /70 et soutenance ; justifier les choix et présenter les limites sans promettre une conformité juridique automatique.", "last_page": 55, "source_kind": "activity", "source_title": "Évaluation et projet sectoriel"}, {"id": "n4-s10-activite", "level": 4, "step": 10, "kind": "activite", "title": "Ressources et suite du parcours", "page": 56, "instruction": "Définissez les indicateurs et revues après le pilote. Livrable : Un calendrier, un responsable et trois critères de décision pour poursuivre, corriger ou arrêter.", "last_page": 59, "source_kind": "activity", "source_title": "Ressources et suite du parcours"}, {"id": "n4-cas-1", "leve